/** Temporary public-Run workload, root-controlled timing; no benchmark-only Product entry. */
export const MODES = ["static-off", "legacy-custom-off", "declared-custom-off", "legacy-terminal-none", "terminal-none", "legacy-terminal-execution", "terminal-execution", "legacy-terminal-raw", "terminal-raw", "diagnostics-on"] as const;
export type Mode = typeof MODES[number];

export async function workload(api: typeof import("../../../src/index.ts"), mode: Mode, n: number, directory: string) {
  let executionCount = 0;
  let terminalCount = 0;
  const selectFirst = (context: import("../../../src/index.ts").AdmissionPolicyContext) => {
    const candidate = context.candidates.find(item => item.canAdmit);
    return candidate === undefined ? { kind: "wait" as const } : { kind: "select" as const, taskId: candidate.taskId };
  };
  const custom = mode === "legacy-custom-off" || mode === "declared-custom-off";
  const effect = (context: import("../../../src/index.ts").SchedulerMeasurementContext) => {
    if (mode.endsWith("execution")) {
      if (context.execution.admittedTaskIds.length !== n) throw new Error("execution facts mismatch");
    }
    if (mode.endsWith("raw")) {
      if (context.rawMeasurement.discrete.admittedCount !== n) throw new Error("raw facts mismatch");
    }
    terminalCount++;
  };
  const terminal = mode.includes("terminal");
  const declared = terminal && !mode.startsWith("legacy");
  const contextNeeds: readonly (keyof import("../../../src/index.ts").SchedulerMeasurementContext)[] = mode.endsWith("execution") ? ["execution"] : mode.endsWith("raw") ? ["rawMeasurement"] : [];
  const result = await api.run(api.defineConfig({
    checks: Array.from({ length: n }, (_, i) => ({
      checkId: `check-${String(i).padStart(4, "0")}`, displayName: `Check ${i}`,
      execute: () => { executionCount++; return { status: "passed" as const, data: {} }; }
    })),
    outputs: { machinePublication: { enabled: false }, progressRendering: { enabled: false }, diagnosticLogging: { enabled: mode === "diagnostics-on", directory } },
    scheduler: { maxParallel: 8,
      admissionPolicy: custom ? { kind: "custom", strategy: { kind: "simple", decide: mode === "declared-custom-off" ? { contextNeeds: ["candidates", "runtime"], callback: selectFirst } : selectFirst } } : { kind: "static" },
      terminalEffects: terminal ? [declared ? { contextNeeds, callback: effect } : effect] : []
    }
  }));
  if (result.kind !== "completed" || executionCount !== n || terminalCount !== (terminal ? 1 : 0)) throw new Error(`workload did not close: ${mode}/${n}/${result.kind}`);
  return { kind: result.kind, executionCount, terminalCount, terminalStatus: result.outputs.terminalEffects.status, diagnosticStatus: result.outputs.diagnosticLogging.status };
}

import { resolve } from "node:path";
import { mkdirSync } from "node:fs";
import { workload, type Mode } from "./workload.ts";
const [sourceRoot, modeInput, nInput, iterationsInput = "12"] = process.argv.slice(2);
if (sourceRoot === undefined || modeInput === undefined || nInput === undefined) throw new Error("sourceRoot mode n iterations");
const api: typeof import("../../../src/index.ts") = await import(resolve(sourceRoot, "index.ts"));
const n = Number(nInput), iterations = Number(iterationsInput), mode = modeInput as Mode;
const directory = resolve("tmp/optimization-wave-20261013/scheduler-needs-bench/output", String(process.pid));
mkdirSync(directory, { recursive: true });
for (let i=0;i<3;i++) await workload(api, mode, n, directory);
const samples: number[] = [];
for(let i=0;i<iterations;i++) {
  const start = performance.now();
  const facts = await workload(api, mode, n, directory);
  samples.push(performance.now()-start);
  if(i===iterations-1) process.stdout.write(JSON.stringify({sourceRoot, mode, n, p:8, shape:"wide-independent", iterations, samples, facts})+"\n");
}

/** Temporary reproducible analysis of frozen raw evidence; no additional sampling. */
const base = "tmp/optimization-wave-20261013/scheduler-needs-bench";
type Row = {
  comparison: string;
  pair: string;
  round: number;
  lane: "A" | "B";
  sample: {
    mode: string;
    n: number;
    p: number;
    samples: number[];
    facts: {
      kind: string;
      executionCount: number;
      terminalCount: number;
      terminalStatus: string;
      diagnosticStatus: string;
    };
  };
};
const raw = await Bun.file(`${base}/timing.final.ndjson`).text();
const rows: Row[] = raw.trim().split("\n").map(line => JSON.parse(line));
const median = (values: number[]) => {
  const sorted = [...values].sort((a,b) => a-b);
  const middle = Math.floor(sorted.length / 2);
  return sorted.length % 2 === 1 ? sorted[middle]! : (sorted[middle-1]! + sorted[middle]!) / 2;
};
const distribution = (values: number[]) => {
  const sorted = [...values].sort((a,b) => a-b);
  const middle = median(values);
  return { count: values.length, median: middle, p95: sorted[Math.ceil(values.length * .95)-1]!, mad: median(values.map(value => Math.abs(value-middle))) };
};
const groups = new Map<string, Row[]>();
for (const row of rows) {
  const {sample} = row;
  if (sample.p !== 8 || ![8,128].includes(sample.n) || sample.samples.length !== 12 || sample.samples.some(value => !Number.isFinite(value) || value < 0)) throw Error("invalid sample");
  const terminal = sample.mode.includes("terminal");
  if (sample.facts.kind !== "completed" || sample.facts.executionCount !== sample.n || sample.facts.terminalCount !== (terminal ? 1 : 0) || sample.facts.terminalStatus !== (terminal ? "succeeded" : "disabled") || sample.facts.diagnosticStatus !== (sample.mode === "diagnostics-on" ? "succeeded" : "disabled")) throw Error("guard mismatch");
  const key = `${row.comparison}/${sample.n}/${row.pair}`;
  const group = groups.get(key) ?? [];
  group.push(row);
  groups.set(key, group);
}
const cells = [...groups].map(([key, group]) => {
  if (group.length !== 8 || group.map(row => row.lane).join("") !== "ABBABAAB") throw Error("ABBA/BAAB protocol mismatch");
  const a = distribution(group.filter(row => row.lane === "A").flatMap(row => row.sample.samples));
  const b = distribution(group.filter(row => row.lane === "B").flatMap(row => row.sample.samples));
  const pairedBatchChanges = Array.from({length:4},(_,index) => {
    const adjacent = group.slice(index*2,index*2+2);
    const before = median(adjacent.find(row => row.lane === "A")!.sample.samples);
    const after = median(adjacent.find(row => row.lane === "B")!.sample.samples);
    return (after/before-1)*100;
  });
  return {key, comparison:group[0]!.comparison, n:group[0]!.sample.n, pair:group[0]!.pair, a,b, deltaMs:b.median-a.median, deltaPercent:(b.median/a.median-1)*100, pairedBatchChanges, pairedMedian:median(pairedBatchChanges), pairedMinimum:Math.min(...pairedBatchChanges), pairedMaximum:Math.max(...pairedBatchChanges), pairedWins:pairedBatchChanges.filter(change => change<0).length};
});
if (rows.length !== 160 || cells.length !== 20) throw Error("incomplete matrix");
await Bun.write(`${base}/analysis.final.json`, JSON.stringify({rawSha256:new Bun.CryptoHasher("sha256").update(raw).digest("hex"), rowCount:rows.length, timedRuns:1920, warmRuns:480, quantile:"nearest-rank p95; median average of two central observations; MAD median absolute deviation; four adjacent opposite-lane batch pairs per cell",cells},null,2)+"\n");
for (const cell of cells) {
  const fmt = (value: number) => value.toFixed(3);
  console.log(`| ${cell.n} | ${cell.pair.split(":")[0]} | ${fmt(cell.a.median)} / ${fmt(cell.a.p95)} / ${fmt(cell.a.mad)} | ${fmt(cell.b.median)} / ${fmt(cell.b.p95)} / ${fmt(cell.b.mad)} | ${cell.deltaPercent.toFixed(2)}% (${cell.deltaMs.toFixed(3)} ms) | ${cell.pairedMinimum.toFixed(2)}% … ${cell.pairedMaximum.toFixed(2)}% | ${cell.pairedWins}/4 |`);
}
